        vm.prank(callerAddr);
        c.airDrop(); // first airdrop sets balance to 20 (and reference enforces hasNoBalance so first succeeds)

        // If startWithBalance == false, we need the caller to have zero initial balance. To achieve that,
        // deploy a fresh caller with zero balance and call nothing further. But above we already did an airdrop.
        // So instead, restructure: only do initial airdrop when startWithBalance is true.
    }
