// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz over a simple uint256 seed which we map to create distinct CallerContracts.
    function testFuzz_property(uint256 seed, bool startWithBalance) public {
        // keep domain wide
        // deploy a caller contract (it implements supportsToken expected by C)
        CallerContract caller = new CallerContract();
        address callerAddr = address(caller);

        // ensure the caller is the one calling c
        if (startWithBalance) {
            // first call to airDrop to create a non-zero balance
            vm.prank(callerAddr);
            c.airDrop();
            // now tokenBalance[callerAddr] == 20 in reference
            uint pre = c.tokenBalance(callerAddr);
            assertTrue(pre == 20);
        } else {
            // ensure zero balance
            uint pre = c.tokenBalance(callerAddr);
            assertTrue(pre == 0);
        }

        // Now perform the test call: call airDrop once more from the same caller
        vm.prank(callerAddr);
        c.airDrop();

        // General rule: In the reference, if caller had non-zero balance before this call, the balance must remain unchanged
        // (hasNoBalance prevents additional airdrops). If caller had zero balance, it increases by exactly 20.
        // The mutant that removed hasNoBalance will increase non-zero balances as well.
        uint after = c.tokenBalance(callerAddr);
        if (startWithBalance) {
            // reference: still 20
            assertTrue(after == 20);
        } else {
            // reference: increased from 0 to 20
            assertTrue(after == 20);
        }
    }
}

contract CallerContract {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address that will attempt to receive an airdrop
    function testFuzz_property(address caller) public {
        // keep caller non-zero address
        vm.assume(caller != address(0));

        // Arrange: give the caller an initial non-zero tokenBalance by directly calling airDrop once
        // To call airDrop successfully, the caller must be a Bank (i.e., msg.sender must return the keccak256 of "Nu Token").
        // We deploy a minimal Bank-like helper that returns the correct supportsToken value and forward calls as that address.
        BankHelper helper = new BankHelper();

        // make helper act as the caller for setup
        vm.prank(address(helper));
        // helper will call c.airDrop() on its own (so msg.sender inside supportsToken is helper and matches)
        helper.callAirDrop(address(c));

        // After this, helper has tokenBalance 20. Now we simulate that same caller (EOA) has a non-zero balance by
        // directly manipulating by having helper transfer its tokenBalance mapping key to the fuzzed caller via a helper bridge.
        // But we cannot modify internal mapping of C directly. Instead, we will simulate the scenario by having the fuzzed caller
        // itself first receive an airdrop (so caller's tokenBalance is non-zero). To do that, the caller must be a Bank-like entity.
        // So we deploy a BankLike at the caller's address by using CREATE2 is not available, but we can instead require the fuzzed
        // caller to be used as the address of a freshly deployed helper via vm.prank and a deployer; simpler: we deploy a new
        // BankHelper instance and treat its address as the actor to fuzz — to still let the fuzzer vary which helper (actor) is tested,
        // we use the provided fuzzed `caller` to seed which of two helpers we use by selecting via uint256(uint160(caller))%2.

        // create two helper accounts and pick one deterministically based on fuzzed caller
        BankHelper h0 = helper;
        BankHelper h1 = new BankHelper();
        BankHelper actor = (uint256(uint160(caller)) % 2 == 0) ? h0 : h1;

        // actor obtains an airdrop once so its balance is non-zero under the reference contract
        vm.prank(address(actor));
        actor.callAirDrop(address(c));

        // Confirm precondition: actor now has non-zero tokenBalance
        uint before = c.tokenBalance(address(actor));
        vm.assume(before != 0);

        // Act: actor attempts to call airDrop again (this should be blocked by hasNoBalance in the reference)
        bool ok;
        vm.prank(address(actor));
        try c.airDrop() { ok = true; } catch { ok = false; }

        // The universal property: for ANY actor that starts with a non-zero tokenBalance, the reference contract must prevent airDrop
        // from succeeding (so ok==false). The mutant (without hasNoBalance) would allow ok==true for some such actor.
        assertTrue(!ok);
    }
}

// Minimal helper that mimics Bank with supportsToken and can call airDrop on C
contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirDrop(address cAddr) external {
        C(cAddr).airDrop();
    }
}

