pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    BankLike helper;

    function setUp() public { 
        c = new C();
        // helper simply returns the expected keccak256("Nu Token") so supportsToken modifier passes
        helper = new BankLike();
    }

    // fuzzed params: an address 'actor' and a nonzero starting balance 'startBal'
    function testFuzz_property(address actor, uint256 startBal) public {
        // keep actor usable and startBal in a reasonable range and non-zero
        vm.assume(actor != address(0));
        startBal = bound(startBal, 1, type(uint256).max / 2);

        // fund actor to pay gas (not strictly necessary but safe)
        vm.deal(actor, 1 ether);

        // set up: give the actor an initial balance by using airDrop once when they have zero balance
        // but airDrop requires msg.sender to be a Bank-like contract in supportsToken modifier: c expects Bank(msg.sender).supportsToken()
        // so we must call airDrop from a contract that returns the proper bytes32; helper does that and forwards the tx as actor

        // first call: have helper call c.airDrop on behalf of actor to set initial non-zero balance
        // we need helper to act as msg.sender for supportsToken check, but tokenBalance is keyed by tx.origin or by msg.sender? In C, tokenBalance[msg.sender] is used, so tokenBalance will be recorded under helper address. To ensure the tested 'actor' is the key, we make a tiny proxy that calls c.airDrop with delegatecall-like effect by having helper call c.airDrop while encoding actor into tokenBalance: this is not possible. Instead, we use a different approach: we will manipulate tokenBalance by making calls from the actor address directly, but supportsToken compares keccak256("Nu Token") == Bank(msg.sender).supportsToken() so msg.sender must be a contract that returns that value. Therefore we deploy a Caller contract that has an owner (actor) and whose supportsToken returns the correct value; actor will own the Caller and we will make the Caller forward calls setting tokenBalance[callerAddress].

        // Deploy a Caller contract whose address will be used as msg.sender when calling c.airDrop;
        // we will treat the Caller contract address as the key k in tokenBalance. We fuzz over that caller address by deriving it from the fuzzed 'actor' via deterministic deployment using CREATE2 would be complex; instead we allow the fuzzer to pick 'actor' but we will deploy a small Caller and set its owner to actor so we still use the fuzzed actor to control the Caller.

        Caller caller = new Caller(address(c));
        // ensure caller.owner is actor
        caller.setOwnerForTest(actor);

        // Now have the caller contract (its address is the key k) perform initial airDrop to get a non-zero balance
        // Actor must execute the call from the Caller, so prank as the caller's address
        vm.prank(address(caller));
        c.airDrop();

        // confirm initial balance is 20
        uint256 before = c.tokenBalance(address(caller));
        assertTrue(before == 20);

        // Now simulate the situation: the key address (address(caller)) has a non-zero balance. Call airDrop again from same caller.
        vm.prank(address(caller));
        // Use try/catch to ensure we capture whether call reverts; reference should revert due to hasNoBalance, so ok will be false for reference
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the second attempt, read the balance
        uint256 after = c.tokenBalance(address(caller));

        // GENERAL ASSERTION: For the reference contract, a subsequent airDrop from the same caller when their balance is already non-zero must NOT increase their tokenBalance.
        // We assert that either the second call reverted (ok == false) and balance unchanged, or it succeeded but balance still equals the previous value.
        // This single assertTrue encodes that invariant by checking after == before (the reference satisfies this for all admissible inputs),
        // while the mutant (which removed hasNoBalance) will allow after == before + 20 for some inputs, causing this assertion to fail.
        assertTrue(after == before);
    }
}

// Minimal helper contracts
contract BankLike {
    function supportsToken() external pure returns (bytes32){
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

// Caller acts as a contract that will be the msg.sender for c.airDrop; it returns the expected supportsToken when queried.
contract Caller is BankLike {
    address public owner;
    C public target;
    constructor(address _target) {
        owner = msg.sender; // initial owner is deployer (test), but test will override for fuzzed actor
        target = C(_target);
    }
    // test helper to set owner to the fuzzed actor address
    function setOwnerForTest(address _owner) external {
        owner = _owner;
    }

    // fallback to call airDrop on target as this contract's address
    function callAirDrop() external {
        require(msg.sender == owner);
        target.airDrop();
    }

    // ensure when test pranks address(caller) and calls c.airDrop(), c sees msg.sender == address(this)
    // For convenience, expose a function to allow test to have this contract call directly
    receive() external payable {}
}

