pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    BankHelper bank;

    function setUp() public { 
        c = new C();
        bank = new BankHelper();
    }

    // fuzz: an actor address that will be the caller, and an initial non-zero balance seed
    function testFuzz_property(address caller, uint256 seed) public {
        // keep caller non-zero and not the zero address
        vm.assume(caller != address(0));
        // bound seed to produce a small-ish non-zero initial balance to avoid overflow concerns
        uint256 initial = bound(seed, 1, 1_000_000);

        // set up the caller to have an existing non-zero balance by directly calling airDrop once
        // airDrop requires msg.sender to answer supportsToken() via Bank(msg.sender).supportsToken()
        // so we must call through our BankHelper which implements supportsToken() and forwards to C.airDrop

        // make BankHelper act as the caller for the first successful airDrop to create a non-zero balance under caller
        // BankHelper will call c.airDrop() while presenting supportsToken() correctly
        // But we need tokenBalance[caller] to be non-zero; tokenBalance mapping uses msg.sender inside airDrop
        // So we must have the caller itself invoke airDrop through a Bank that matches supportsToken().

        // Deploy a per-caller BankForward that will call c.airDrop() while its msg.sender is the caller
        BankForward forward = new BankForward(c);

        // fund caller so it can perform calls (not strictly necessary but conventional)
        vm.deal(caller, 1 ether);

        // have the forwarder be recognized by caller as the Bank (supportsToken() is on Bank(msg.sender) inside C)
        // We need to have caller execute the forwarder's call so that inside c, msg.sender == caller
        // Use vm.prank to make the tx originate from caller, and instruct the forwarder to call airDrop specified times

        vm.prank(caller);
        // call forward to perform `initial` times airDrop to reach a non-zero balance; but each airDrop gives +20.
        // compute repeats needed to reach at least `initial` but keep it small to avoid long loops; instead
        // do a single setup: we want tokenBalance[caller] != 0. Do one airDrop to make it 20 which is non-zero.
        forward.callAirDropOnce(address(bank));

        // verify setup: caller now has non-zero balance
        uint256 before = c.tokenBalance(caller);
        assertTrue(before != 0);

        // Now perform the tested action: have the same caller attempt another airDrop via a Bank that supports the token
        vm.prank(caller);
        // call c.airDrop() directly because inside C it checks Bank(msg.sender).supportsToken(), so msg.sender must be
        // a contract with supportsToken(); thus we call via the BankHelper's proxy function which will make c see msg.sender==caller
        // Achieve this by having the caller call the BankHelper which then calls c.airDrop(); BankHelper.supportsToken returns the expected bytes32
        bank.callAirDrop(address(c));

        // After this call completes, in the reference contract the hasNoBalance modifier prevents increasing an existing non-zero balance.
        // So the invariant: tokenBalance(caller) is unchanged from `before`.
        uint256 afterBalance = c.tokenBalance(caller);

        assertTrue(afterBalance == before);
    }
}

// Minimal Bank helper that has supportsToken() and a function to call airDrop on the token contract
contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // This function is invoked by the caller (an EOA) via vm.prank(caller). It will call c.airDrop() such that
    // inside c.airDrop(), msg.sender == address(this) (the BankHelper). But C expects Bank(msg.sender).supportsToken()
    // to equal keccak256("Nu Token"). Because BankHelper.supportsToken() returns that, calls through this helper succeed.
    function callAirDrop(address token) external {
        C(token).airDrop();
    }
}

// Forward helper: used to create an initial non-zero balance for an arbitrary caller. The caller will call this contract,
// and this contract will call c.airDrop(). Inside c.airDrop(), msg.sender == caller (the original EOA), which allows
// the reference contract to check Bank(msg.sender).supportsToken() — but because the msg.sender is an EOA (no supportsToken),
// that would fail. To ensure supportsToken() check passes, we instead have the forwarder be a contract that the caller calls
// and that contract calls c.airDrop(); inside c.airDrop() msg.sender is the forwarder, so forwarder must implement supportsToken().
// To simplify, we make the forwarder implement supportsToken() and call c.airDrop() on behalf of the caller.
contract BankForward {
    C immutable token;
    constructor(C _token) { token = _token; }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    // Called by the EOA `caller` via vm.prank(caller); this function calls token.airDrop() such that
    // inside token.airDrop(), msg.sender == address(this) (the forwarder) and supportsToken() check passes.
    function callAirDropOnce(address /*bankPlaceholder*/) external {
        token.airDrop();
    }
}

