pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reporter rep;

    function setUp() public { c = new C(); rep = new Reporter(); }

    // Fuzzed params: caller and a third-party addr k
    function testFuzz_property(address caller, address k) public {
        // keep addresses distinct and non-zero
        vm.assume(caller != address(0));
        vm.assume(k != address(0));
        vm.assume(k != caller);

        // reporter contract's supportsToken() returns correct hash; we must call airDrop via reporter (msg.sender = reporter)
        // ensure reporter is the msg.sender by having caller perform an external call to reporter which forwards the call
        // We need caller to be an EOA for vm.prank to work

        // Record balance of third-party k before
        uint before = c.tokenBalance(k);

        // Make caller be the tx.origin/prank and have caller call reporter which will call c.airDrop()
        vm.prank(caller);
        rep.doAirDrop(address(c));

        // After the operation, in the correct reference contract, balances of other addresses (k != caller) remain unchanged
        uint after = c.tokenBalance(k);

        // Single assertion: reference must maintain third-party balances for all admissible inputs; mutant that removed hasNoBalance can alter other addresses
        assertTrue(after == before);
    }
}

// Minimal helper that calls C.airDrop() from itself so msg.sender == Reporter
contract Reporter {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function doAirDrop(address caddr) external {
        C(caddr).airDrop();
    }
}

