pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: two distinct actors to exercise that the lock does not permanently block others
    function testFuzz_property(address actor1, address actor2) public {
        vm.assume(actor1 != address(0));
        vm.assume(actor2 != address(0));
        vm.assume(actor1 != actor2);

        // Ensure actors have EOA-like balances if needed (not strictly required here but harmless)
        vm.deal(actor1, 1 ether);
        vm.deal(actor2, 1 ether);

        // Each actor must be set up so that supportsToken() call from their address returns keccak256("Nu Token").
        // The contract C expects Bank(msg.sender).supportsToken() to match keccak256("Nu Token").
        // Since the fuzzer supplies raw addresses (EOAs with no code), we need to deploy a tiny forwarder 'BankProxy'
        // per actor so that calling from that address will cause msg.sender inside supportsToken() to be the proxy.
        // BUT C's supportsToken modifier does: Bank(msg.sender).supportsToken()
        // So we must call airDrop while the msg.sender is an address with code implementing supportsToken().

        // Deploy two minimal Bank helpers that implement supportsToken() and then have the test call as them.
        BankHelper b1 = new BankHelper();
        BankHelper b2 = new BankHelper();

        // Use vm.prank to make the call originate from the helper addresses; the fuzzer-provided actor1/actor2
        // are unused as msg.senders (we still fuzz them per requirements). We keep them as part of inputs.

        // First actor (helper b1) performs airDrop; should succeed and increase its tokenBalance by 20
        vm.prank(address(b1));
        bool ok1;
        try c.airDrop() {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        // The reference contract always allows a first successful call (with hasNoBalance) for a fresh address.
        // If ok1 == false then airDrop reverted; in either implementation the observable property we assert below
        // must hold for all inputs on the reference. We proceed only if it succeeded to exercise the subsequent call.
        if (!ok1) {
            // If the first call didn't succeed (shouldn't happen with proper C), assert that tokenBalance is 0
            // for b1 and b2. This still reads public getter on c.
            assertTrue(c.tokenBalance(address(b1)) == 0);
            return;
        }

        // After successful airDrop by b1, its balance must be 20 in the reference implementation.
        // More importantly for the mutant, failing to reset the lock will block subsequent calls, so we now
        // have helper b2 attempt airDrop; in the reference this should succeed and give b2 a balance of 20.
        vm.prank(address(b2));
        bool ok2;
        try c.airDrop() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // GENERAL ASSERTION (single assertTrue): In the correct contract, if both calls succeed then both balances are 20.
        // The mutant that never resets _locked will allow the first call but block subsequent calls, causing b2's balance
        // to remain 0 while b1's is 20. We assert that either both have 20 (reference expected) or the first call failed
        // in which case both remain 0; this assertion will be true for the reference for all inputs and violated by the mutant
        // for some inputs (where first succeeds and second is blocked).
        assertTrue(
            (ok1 && ok2 && c.tokenBalance(address(b1)) == 20 && c.tokenBalance(address(b2)) == 20)
            || (!ok1 && c.tokenBalance(address(b1)) == 0 && c.tokenBalance(address(b2)) == 0)
        );
    }
}

contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

