// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: actor who will call airDrop
    function testFuzz_property(address actor) public {
        // Keep actor non-zero address (EOA space is fine)
        vm.assume(actor != address(0));

        // Ensure actor starts with zero token balance in the reference contract
        // (fresh contract and no prior interactions guarantees this, but be explicit)
        assertEq(c.tokenBalance(actor), 0);

        // Run airDrop as actor and observe success (airDrop uses modifiers that call external supportsToken on msg.sender)
        // In the reference, supportsToken() is expected to be available on msg.sender; however, in the provided
        // reference implementation Bank.supportsToken() is external and expects to be called on msg.sender.
        // To satisfy the supportsToken() external call, we need msg.sender to be a contract that responds with
        // keccak256("Nu Token"). The original problem statement's Bank returns that value. Thus we must deploy
        // a minimal helper Bank-like contract and impersonate it as the caller.

        // Deploy helper that implements supportsToken() returning keccak256("Nu Token")
        BankLike helper = new BankLike();

        // Ensure helper has zero tokenBalance initially
        assertEq(c.tokenBalance(address(helper)), 0);

