            // To keep the test simple and still universal, we'll map the fuzzed 'actor' into either the helper address or the
            // actor EOA: if actor equals address(helper) we perform the build-up, otherwise we treat it as an arbitrary EOA
            // and do not modify chain state further.

            if (actor == address(helper)) {
                // prank from helper (it is a BankHelper and also an externally-owned deployer here)
                vm.prank(address(helper));
                c.airDrop();
            }
        }

        // If actor equals helper and startBal had a remainder (not multiple of 20), we cannot create non-multiples; leave as-is.
        // Now we attempt the decisive call: have the fuzzed actor call airDrop via the BankHelper when appropriate.

        bool ok;
        // We need the call to be made with msg.sender being a Bank (i.e., returns keccak256('Nu Token')).
        // The c.supportsToken() compares keccak256(abi.encodePacked("Nu Token")) == Bank(msg.sender).supportsToken()
        // So we must call with msg.sender == helper to satisfy supportsToken; since our helper is deployed, use it.

        // If the fuzzed actor is the helper itself, we can prank as helper directly.
        if (actor == address(helper)) {
            vm.prank(address(helper));
            try c.airDrop() {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // For any other actor (an EOA), calling airDrop will fail the supportsToken() check because msg.sender won't be a Bank
            // returning the expected bytes32; thus the call will revert on both reference and mutant. We capture that behavior.
            vm.prank(actor);
            try c.airDrop() {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // SINGLE ASSERTION: For the reference contract, whenever the caller's pre-call tokenBalance != 0, airDrop must revert (ok == false).
        // The mutant that relaxes hasNoBalance to <=10 will allow calls from callers with small positive balances (1..10) to succeed,
        // making ok == true for some inputs. We therefore assert the universal property: if the pre-call balance is not zero then airDrop reverts.

        // Read the pre-call balance from the contract's public getter (we must ensure we read the actual pre-call value; we approximated above
        // by our construction - for actor==helper we built up multiples of 20; for others we left 0). For safety, compute preBal by querying tokenBalance.
        uint256 preBal = c.tokenBalance(actor);

        // The universal property: if preBal != 0 then the call must revert (ok == false) in the reference implementation.
        // This is a single assertTrue reading c via its public getter behavior.
        if (preBal != 0) {
            assertTrue(ok == false);
        } else {
            // If preBal == 0 then a call as a valid Bank (helper) should succeed and set balance to 20.
            // But the single required assertion must be universal; to keep a single assertion we assert that when preBal==0,
            // either the call reverted (because unsupported caller) or it succeeded — both are valid for reference depending on msg.sender.
            // To keep the single required assertion reading c, we assert that preBal==0 implies (ok == true || ok == false) which is tautological,
            // but we cannot assert tautologies. Instead, to comply with the requirement of exactly one assertTrue that the reference satisfies
            // for all inputs and the mutant violates for some, we only assert the meaningful universal case (preBal != 0 => reverted) and do nothing otherwise.
            // Therefore we make a vacuous assertTrue that reads c: tokenBalance(actor) == preBal (i.e., unchanged) — this holds for reference when preBal==0
            // (balance remains 0 if call reverted) and also holds when call succeeded (becomes 20) only if it succeeded; however this would fail.
            // To avoid adding a second assert, we simply assertTrue(preBal == 0 || preBal != 0); // invalid per rules (must read c).

            // To satisfy the test shape rules strictly, we avoid asserting here and only have the single conditional assert above.
        }
    }
}

contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

