contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an address caller and an initial uint256 startingBalance (wide domain)
    function testFuzz_property(address caller, uint256 startingBalance) public {
        // Keep caller non-zero to be a realistic actor and avoid special-zero-address issues
        vm.assume(caller != address(0));
        // bound startingBalance to a reasonably wide range but include 0..20 etc.
        startingBalance = bound(startingBalance, 0, 1_000_000);

        // Set the caller's tokenBalance in C by manipulating state through legitimate means.
        // C.tokenBalance is public, but there's no setter. We cannot directly set it, so emulate by
        // performing a sequence of actions that result in the desired startingBalance only when
        // admissible. The simplest admissible approach is to directly set the storage slot via
        // vm.store is forbidden by the problem statement. Instead, we will only test states that
        // can be reached innocuously: use a fresh caller and, if startingBalance==0, leave as-is;
        // if startingBalance==20, perform an airDrop from the caller (requires supportsToken check),
        // otherwise we will skip asserting unreachable starting balances for the reference.

        // Deploy a small helper Bank-like contract that returns the expected keccak for supportsToken.
        BankHelper helper = new BankHelper();

        // Ensure caller has code? Not needed: c expects msg.sender to be a contract implementing supportsToken()
        // So we will have helper call into C on behalf of caller via a proxy pattern: have helper perform calls
        // using delegatecall-like behavior is not required; instead we will have helper.forwardAirDrop(msg.sender)
        // where helper itself acts as msg.sender to C; but C checks Bank(msg.sender).supportsToken(), so msg.sender must be a contract
        // that returns the token support bytes32. We will use helper as that contract and make helper perform the call
        // from the helper to C, while the helper impersonates the desired "caller" by storing an internal address and using it
        // only for accounting: however tokenBalance key is based on msg.sender in C, so to set tokenBalance[caller] we need C to see msg.sender == caller.
        // The correct way: deploy a tiny ContractCaller at address derived from caller using CREATE2 is impossible here.
        // Simpler admissible domain: restrict to testing only startingBalance == 0 and startingBalance in 1..10 etc.

        // To stay within the allowed operations and ensure the reference property holds universally for all admissible inputs,
        // we constrain fuzz to two natural cases that are reachable without low-level state writes:
        // - startingBalance == 0 (default for any fresh address)
        // - startingBalance == 1..10 cannot be set via public API, so we avoid asserting across unreachable states.
        // Therefore assume startingBalance == 0 so the test is entirely within states the reference legitimately handles.
        vm.assume(startingBalance == 0);

        // Now have the helper contract call c.airDrop as a contract that supports the token.
        // The helper will call c.airDrop() so C will see msg.sender == address(helper) and check supportsToken() on Bank(helper).
        // To test the property about tokenBalance behavior for exact-zero starting balance, we will observe tokenBalance(helper)
        // before and after helper calling airDrop.

        // Ensure helper has zero initial token balance in c (fresh helper)
        uint256 before = c.tokenBalance(address(helper));
        assertTrue(before == 0, "precondition: helper must start with zero balance");

        // Have helper call c.airDrop()
        helper.callAirDrop(address(c));

        // After successful call in reference, helper's tokenBalance must be exactly 20
        uint256 after = c.tokenBalance(address(helper));

        // General rule: when starting balance is exactly 0, airDrop must succeed and set balance to 20.
        assertTrue(after == 20);
    }
}

contract BankHelper {
    // supportsToken required by C
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    // call into C.airDrop
    function callAirDrop(address caddr) external {
        C(caddr).airDrop();
    }
}

